package com.bank.jvm;

import java.util.logging.*;

// Starts a CPU-hot worker, then shows how to find it via a thread dump.
public class HighCpuDemo {
    private static final Logger log = Logger.getLogger(HighCpuDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Start the offending thread: a fraud check stuck spinning.
        FraudCheckWorker worker = new FraudCheckWorker();
        Thread hot = new Thread(worker, "fraud-check-spinner");
        hot.start();
        log.info("Started fraud-check worker (it will spin and burn a CPU core)");

        Thread.sleep(2000); // let it heat up

        // Capture a thread dump TWICE a couple seconds apart to find the persistent hotspot.
        ThreadDumpHelper dumper = new ThreadDumpHelper();
        dumper.dumpRunnable("Dump #1");
        Thread.sleep(2000);
        dumper.dumpRunnable("Dump #2");

        worker.stop(); hot.join();
        log.info("Worker stopped; the thread that appeared RUNNABLE in BOTH dumps was the hotspot");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in FraudCheckWorker.java in a real project ───
class FraudCheckWorker implements Runnable {
    private volatile boolean running = true;
    private volatile boolean conditionMet = false; // never set true -> spin forever
    @Override public void run() {
        long wasted = 0;
        // BUG: busy-spin with no sleep/backoff -> pegs a CPU core at 100%.
        while (running && !conditionMet) {
            wasted++;                 // pure CPU burn, no blocking
            if (wasted == Long.MIN_VALUE) conditionMet = true; // effectively never
        }
    }
    void stop() { running = false; }
}

// ─── Would be in ThreadDumpHelper.java in a real project ───
class ThreadDumpHelper {
    private static final Logger log = Logger.getLogger(ThreadDumpHelper.class.getName());
    private final java.lang.management.ThreadMXBean threadBean =
            java.lang.management.ManagementFactory.getThreadMXBean();

    // Capture all thread stacks and highlight RUNNABLE ones (CPU-burning candidates).
    void dumpRunnable(String label) {
        log.info("==== " + label + " (RUNNABLE threads first) ====");
        var infos = threadBean.dumpAllThreads(false, false);
        for (var info : infos) {
            if (info.getThreadState() == Thread.State.RUNNABLE) {
                long cpuNs = threadBean.getThreadCpuTime(info.getThreadId());
                StackTraceElement top = info.getStackTrace().length > 0
                        ? info.getStackTrace()[0] : null;
                log.warning(String.format("RUNNABLE '%s' cpu=%dms top=%s",
                        info.getThreadName(), cpuNs / 1_000_000, top));
            }
        }
    }
}
